#!/usr/bin/env node
// Writes the plain JavaScript that the panel and the custom editors load, next to each TypeScript source.
//
//   node scripts/build-frames.mjs           regenerate (and delete generated files no entry loads any more)
//   node scripts/build-frames.mjs --check   exit 1 when a generated file is missing, stale or orphaned, or when an
//                                           entry's import graph still holds a file Orca would transpile
//
// Why: Orca transpiles every .ts/.tsx/.mts/.jsx module a panel or editor frame imports in a worker thread under a
// 2000 ms timer that runs on Orca's busy main thread, and it caches a timed-out result for the life of the process.
// Right after a cold boot or an Orca relaunch the timer wins even for a one-line file, and the panel stays black until
// Orca quits. Plain .js/.mjs is served as it is. So each HTML entry loads `<name>.js`, generated here from `<name>.ts`.
// The worker (src/worker.ts) is not affected: Orca's plugin host transpiles it in its own process with no timer.
//
// No dependencies: Node's built-in module.stripTypeScriptTypes (Node 22.13+/23.2+) blanks the types out, so every
// line and column of `<name>.js` is the same as in `<name>.ts` (only trailing spaces are trimmed). Imports that end
// up empty (`import { type A } from './a.ts'`) are dropped the way Orca's transpiler drops them, so a frame never
// loads a worker-only module, and relative `.ts` specifiers become `.js`. The sources must be erasable TypeScript:
// `scripts/dev.sh check` runs tsc with --erasableSyntaxOnly --verbatimModuleSyntax.
import { readFileSync, readdirSync, realpathSync, rmSync, writeFileSync } from 'node:fs'
import module from 'node:module'
import { dirname, extname, join, normalize, sep } from 'node:path'
import { fileURLToPath } from 'node:url'

export const ROOT = fileURLToPath(new URL('../', import.meta.url))
/** Extensions Orca transpiles when a frame imports them (its source-module rule). */
export const TRANSPILED = new Set(['.ts', '.tsx', '.mts', '.cts', '.jsx'])
/** The last line of every generated file; also how --check finds orphans. */
export const BANNER = '// Generated by scripts/build-frames.mjs from the .ts file of the same name. Do not edit.'

const posix = (p) => p.split(sep).join('/')

/** The HTML entries of the panels (ui: html) and custom editors in the manifest, as root-relative paths. */
export function htmlEntries(root = ROOT) {
  const { contributes = {} } = JSON.parse(readFileSync(join(root, 'orca-plugin.json'), 'utf8'))
  return [...(contributes.panels ?? []).filter((p) => p.ui === 'html'), ...(contributes.customEditors ?? [])].map((x) => x.entry)
}

/** Relative `src` of every <script> in an HTML file. */
export function scriptSources(html) {
  return [...html.matchAll(/<script\b[^>]*\bsrc\s*=\s*["']([^"']+)["'][^>]*>/gi)].map((m) => m[1])
}

/**
 * Static and dynamic import specifiers of an ES module (JS, after type stripping), with their offsets.
 * A line-anchored scan: the sources keep imports at the top level, one statement each. test/frames-js.test.mjs
 * links every generated module with Node's own parser, so a specifier this misses fails there.
 */
export function importsOf(code) {
  const out = []
  const statics = /^[ \t]*(?:import|export)\b(?:[^'";]*?\bfrom\s*|\s*)(['"])([^'"\n]+)\1/gm
  for (const m of code.matchAll(statics)) out.push({ specifier: m[2], start: m.index + m[0].length - m[2].length - 1, end: m.index + m[0].length - 1 })
  for (const m of code.matchAll(/\bimport\s*\(\s*(['"])([^'"\n]+)\1/g)) out.push({ specifier: m[2], start: m.index + m[0].length - m[2].length - 1, end: m.index + m[0].length - 1, dynamic: true })
  return out.sort((a, b) => a.start - b.start)
}

const blank = (s) => s.replace(/[^\n]/g, ' ')

/** TypeScript source -> the JavaScript a frame loads. Throws on syntax that cannot be erased. */
export function toJs(ts) {
  let js = module.stripTypeScriptTypes(ts, { mode: 'strip' })
  // Orca's transpiler (sucrase) drops an import with only type bindings; keeping `import {} from` would load the module.
  js = js.replace(/^[ \t]*import\s*\{[\s,]*\}\s*from\s*(['"])[^'"\n]+\1[ \t]*;?/gm, blank)
  for (const m of importsOf(js).reverse()) {
    if (!/^\.\.?\//.test(m.specifier) || extname(m.specifier) !== '.ts') continue
    js = js.slice(0, m.start) + m.specifier.slice(0, -3) + '.js' + js.slice(m.end)
  }
  js = js.replace(/[ \t]+$/gm, '')
  return (js.endsWith('\n') ? js : js + '\n') + BANNER + '\n'
}

/**
 * Walks every HTML entry's graph. Returns the files to write ({ path: code }, root-relative), the graph per entry,
 * and problems (a transpiled file or a bare import a frame would load, a missing file).
 */
export function build(root = ROOT) {
  const files = new Map()
  const graphs = new Map()
  const problems = []
  const read = (rel) => readFileSync(join(root, rel), 'utf8')
  const exists = (rel) => { try { read(rel); return true } catch { return false } }
  for (const entry of htmlEntries(root)) {
    const seen = new Set([entry])
    const queue = []
    const add = (from, specifier) => {
      if (specifier === 'orca' || specifier.startsWith('orca/')) return
      if (!/^\.\.?\//.test(specifier)) return problems.push(`${from}: imports "${specifier}"; a frame can only load relative files`)
      const rel = posix(normalize(join(dirname(from), specifier.split(/[?#]/)[0])))
      if (TRANSPILED.has(extname(rel))) problems.push(`${from}: loads ${rel}, which Orca transpiles under its 2000 ms budget`)
      if (!seen.has(rel)) { seen.add(rel); queue.push(rel) }
    }
    for (const src of scriptSources(read(entry))) add(entry, src)
    while (queue.length) {
      const rel = queue.shift()
      let code
      if (extname(rel) === '.js' && exists(rel.replace(/\.js$/, '.ts'))) {
        const ts = rel.replace(/\.js$/, '.ts')
        try { code = toJs(read(ts)) } catch (e) { problems.push(`${ts}: ${e.message}`); continue }
        files.set(rel, code)
      } else if (exists(rel)) {
        code = read(rel)
      } else {
        problems.push(`${rel}: no such file (imported by the ${entry} graph)`)
        continue
      }
      for (const m of importsOf(code)) add(rel, m.specifier)
    }
    graphs.set(entry, [...seen])
  }
  return { files, graphs, problems }
}

/** Generated files on disk (any .js under src/ ending in the banner), root-relative. */
export function generatedOnDisk(root = ROOT) {
  return readdirSync(join(root, 'src'), { recursive: true })
    .map((f) => posix(join('src', f)))
    .filter((f) => f.endsWith('.js') && readFileSync(join(root, f), 'utf8').trimEnd().endsWith(BANNER))
    .sort()
}

/** Differences between the generated files on disk and a fresh build: missing, stale or orphaned files. */
export function staleness(root = ROOT, files = build(root).files) {
  const out = []
  for (const [rel, code] of files) {
    let disk = null
    try { disk = readFileSync(join(root, rel), 'utf8') } catch {}
    if (disk === null) out.push(`${rel}: missing`)
    else if (disk !== code) out.push(`${rel}: stale`)
  }
  for (const rel of generatedOnDisk(root)) if (!files.has(rel)) out.push(`${rel}: no entry loads it any more`)
  return out
}

if (process.argv[1] && fileURLToPath(import.meta.url) === realpathSync(process.argv[1])) {
  process.removeAllListeners('warning') // stripTypeScriptTypes is "experimental" and says so on every run
  const check = process.argv.includes('--check')
  const { files, problems } = build()
  if (problems.length) { console.error(problems.join('\n')); process.exit(1) }
  if (check) {
    const stale = staleness(ROOT, files)
    if (stale.length) { console.error(`${stale.join('\n')}\nRun: node scripts/build-frames.mjs`); process.exit(1) }
    console.log(`frames: ${files.size} generated files are up to date`)
  } else {
    for (const [rel, code] of files) writeFileSync(join(ROOT, rel), code)
    const orphans = generatedOnDisk().filter((rel) => !files.has(rel))
    for (const rel of orphans) rmSync(join(ROOT, rel))
    console.log(`frames: wrote ${files.size} files${orphans.length ? `; deleted ${orphans.join(', ')} (no entry loads them)` : ''}`)
  }
}
